const DOC = '/commulingo/docs/lenin-materialism-and-empirio-criticism-1909';

function t(ko, en) {
    return { ko, en };
}

// koFeedback/enFeedback are per-choice feedback lines, authored in the same
// order as the choices; ordered() reorders them alongside so the stored arrays
// stay aligned with the stored choices (correct answer first).
function q(answer, koPrompt, enPrompt, koChoices, enChoices, koExplanation, enExplanation, koFeedback, enFeedback, source) {
    function ordered(items) {
        return [
            items[answer],
            ...items.filter((_, index) => index !== answer),
        ];
    }
    const question = {
        type: 'multiple_choice',
        points: 0,
        prompt: t(koPrompt, enPrompt),
        choices: { ko: ordered(koChoices), en: ordered(enChoices) },
        answer: 0,
        explanation: t(koExplanation, enExplanation),
    };
    if (koFeedback && enFeedback) {
        question.choiceFeedback = { ko: ordered(koFeedback), en: ordered(enFeedback) };
    }
    if (source) question.source = source;
    return question;
}

// A verbatim passage: Korean from the CommuLingo translation, English from the
// Lenin Collected Works text; anchor is a heading id of the document (chapter-1-3).
function src(anchor, labelKo, labelEn, quoteKo, quoteEn) {
    return { href: `${DOC}#${anchor}`, label: t(labelKo, labelEn), quote: t(quoteKo, quoteEn) };
}

// Guided reading (2026-10-28): the context line shown above the passage.
function read(contextKo, contextEn, question) {
    return { ...question, context: t(contextKo, contextEn) };
}

function lesson(ch, level, titleKo, titleEn, questions) {
    return {
        id: `materialism-empiriocriticism-ch${String(ch).padStart(2, '0')}-${level}`,
        level,
        title: t(titleKo, titleEn),
        questions: questions.map((item, index) => ({
            ...item,
            // An explicit id (a replaced question, scripts/check-commulingo-question-ids.js) wins over the position.
            id: item.id || `q${index + 1}`,
            points: level === 'advanced' ? 3 : 2,
        })),
    };
}

function map(ko, en) {
    return {
        ko: ko.map(([title, text]) => ({ title, text })),
        en: en.map(([title, text]) => ({ title, text })),
    };
}

function brief(conceptKo, conceptEn, termKo, termEn, modernKo, modernEn, focusKo, focusEn) {
    function sections(concepts, term, modern, focus, labels) {
        return [
            { title: labels[0], items: concepts.map(([title, text]) => title + ': ' + text) },
            { title: labels[1], text: term },
            { title: labels[2], text: modern },
            { title: labels[3], text: focus },
        ];
    }
    return {
        ko: sections(conceptKo, termKo, modernKo, focusKo, ['핵심 개념 먼저', '용어 풀이', '현대 적용', '이 장의 초점']),
        en: sections(conceptEn, termEn, modernEn, focusEn, ['Core concepts first', 'Term guide', 'Modern application', 'Chapter focus']),
    };
}

// A typed concept diagram rendered above the brief: kind 'flow' takes
// { title, steps: [{ label, note }] }, kind 'contrast' takes
// { title, left: { heading, rows }, right: { heading, rows } } per language.
function diagram(kind, ko, en) {
    return { kind, ko, en };
}

function chapter(ch, anchor, titleKo, titleEn, summaryKo, summaryEn, focusKo, focusEn, conceptKo, conceptEn, termKo, termEn, modernKo, modernEn, basic, advanced, extras) {
    return {
        id: `materialism-empiriocriticism-ch${String(ch).padStart(2, '0')}`,
        volumeNumber: 1,
        chapterNumber: ch,
        title: t(titleKo, titleEn),
        sourceUrl: `${DOC}#${anchor}`,
        summary: t(summaryKo, summaryEn),
        learningFocus: t(focusKo, focusEn),
        conceptBrief: brief(conceptKo, conceptEn, termKo, termEn, modernKo, modernEn, focusKo, focusEn),
        conceptMap: map(conceptKo, conceptEn),
        lessons: [
            lesson(ch, 'basic', `${titleKo} 기본`, `${titleEn}: Basics`, basic),
            lesson(ch, 'advanced', `${titleKo} 심화`, `${titleEn}: Advanced`, advanced),
        ],
        ...(extras || {}),
    };
}

// Guided reading (2026-10-28): one reading lesson per unit, made of the six to
// eight questions the unit picks (extras.reading.picks, e.g. 'basic:2', in reading
// order). Lesson ids are new (lenin-mec-chNN) so no question id is reused.
function readingChapters(units) {
    return units.map(unit => {
        const id = `lenin-mec-ch${String(unit.chapterNumber).padStart(2, '0')}`;
        const byLevel = Object.fromEntries(unit.lessons.map(item => [item.level, item.questions]));
        const questions = unit.reading.picks.map(pick => {
            const [level, number] = pick.split(':');
            const { id: oldId, ...question } = byLevel[level][Number(number) - 1];
            return question;
        });
        return {
            id,
            volumeNumber: 6,
            chapterNumber: unit.chapterNumber,
            title: unit.title,
            sourceUrl: unit.sourceUrl,
            summary: unit.summary,
            lessons: [{
                id: `${id}-basic`,
                level: 'basic',
                title: unit.title,
                questions: questions.map((question, index) => ({ ...question, id: `q${index + 1}`, points: 2 })),
            }],
        };
    });
}

